import os
import re

def ham_code_bv_skill(ID_SKIN, Files_MOD):
    code_bv_skill = b''
    Code_bv_skill = Files_MOD+ID_SKIN+'_Back.xml'
    if os.path.exists(Code_bv_skill):
        with open(Code_bv_skill, 'rb') as f: code_bv_skill = f.readlines()
        result_lines = []
        found = False
        for line in code_bv_skill:
            if found:
                result_lines.append(line)
            if b'<Action tag="' in line:
                found = True
        filtered_lines = [line for line in result_lines if b'<Condition' not in line]
        filtered_lines = [line for line in filtered_lines if line.strip() not in [b'</Action>', b'</Project>']]
        code_bv_skill = b''.join(filtered_lines)
        code_bv_skill = code_bv_skill
    return code_bv_skill
    
